import{_ as p,C as a,o,c as i,j as t,a as l,E as n,a6 as s}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"实现最高生产力的三步日常作息","description":"","frontmatter":{"title":"实现最高生产力的三步日常作息","originalTitle":"The 3-Part Daily Routine For Maximum Productivity","date":"2022-07-23","originalUrl":"https://thedankoe.com/letters/the-3-part-daily-routine-for-maximum-productivity/","minutes":16,"sourceHash":"e570b2e4973ff796b970f1dc107b9a2b8986735a608b1c0b8bad622072233611","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-3-part-daily-routine-for-maximum-productivity/"}]]},"headers":[],"relativePath":"letters/the-3-part-daily-routine-for-maximum-productivity.md","filePath":"letters/the-3-part-daily-routine-for-maximum-productivity.md"}'),h={name:"letters/the-3-part-daily-routine-for-maximum-productivity.md"};function m(c,e,u,d,f,b){const r=a("ArticleMeta");return o(),i("div",null,[e[0]||(e[0]=t("h1",{id:"实现最高生产力的三步日常作息",tabindex:"-1"},[l("实现最高生产力的三步日常作息 "),t("a",{class:"header-anchor",href:"#实现最高生产力的三步日常作息","aria-label":'Permalink to "实现最高生产力的三步日常作息"'},"​")],-1)),n(r),e[1]||(e[1]=s('<p><a href="https://www.youtube.com/embed/qdXFeyzq7HE?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我一直对西方的工作文化存在某种程度的反感。</p><ul><li>每周工作80小时。</li><li>高压环境。</li><li>几乎没有休息和恢复的时间。</li></ul><p>这在我看来从来都不“对劲”。</p><p>既然知道工作2-3小时后我的工作质量就会下降，我为什么还要浪费整整一天的时间？</p><p>很长一段时间以来，这一直是个热门话题。我相信它已经开始塑造创作者经济和远程工作。</p><p>4小时工作制、专注单一目标以及有意义的工作，正在我们推特（Twitter）的这个小圈子里成为常态——而我绝不希望情况有任何改变。我们正在创造一个充满激情的个体的未来，他们将创造出改变世界的作品。</p><p>古罗马人、古希腊人、史蒂夫·乔布斯（Steve Jobs）、查尔斯·达尔文（Charles Darwin），以及无数有远见的人、战略家和创新者，都将他们的成功归功于令人惊讶的极短“工作”时间。</p><p>来自多个领域的作家和创作者，比如海明威（Hemingway）和昆汀·塔伦蒂诺（Tarantino），会把一天中的大部分时间花在泳池边闲逛、和女孩们调情，做着除了他们认为是“工作”之外的所有事情。</p><p>为什么？</p><h2 id="i-生产力悖论" tabindex="-1">I. 生产力悖论 <a class="header-anchor" href="#i-生产力悖论" aria-label="Permalink to &quot;I. 生产力悖论&quot;">​</a></h2><blockquote><p>“人们常说，聪明人工作靠巧劲而非死力，但有创造力的人压根就不工作。”——亚历克斯·苏钟-金·庞（Alex Soojung-Kim Pang）</p></blockquote><p>对于那些像我一样热爱健身房（或任何形式运动）的人来说，你一定明白休息和恢复的重要性。</p><p>想象一下，你为了尽可能“高效”，在健身房里待上8个小时。你会试图在硬拉这种极度消耗神经系统的主项练习上挑战极限，然后接着做辅助动作。在一天之内，你就会把能做的练习全耗光。你甚至可能只是因为老板的吩咐，就跑去再跑个步。</p><p>第二天你还能回到健身房并全力以赴吗？连续5天呢？你还能硬撑着，直到用上带薪休假时间来恢复，然后再重新来过吗？</p><p><em>你的身体会</em> <em>被彻底摧毁</em>_。_</p><p>相反，我们每次去健身房只待45-90分钟。我们以消耗体力为代价来突破自我。我们制定一套日常作息并将其排进每一天的日程中，这样我们就能优先考虑休息、恢复和整体的生活质量（因为我们还有生活的其他部分要去探索）。</p><p>虽然企业文化正在给你发放可观的薪水来激励你保持持久的高强度，但我们必须予以反击。</p><p>高强度是无法持久的。这又不是什么高深复杂的学问。在我们提到“生产力”这个词之前，必须优先考虑可持续性、一致性和创造力。</p><h2 id="ii-填充-清空-使用框架-实现可持续的生产力与创造力" tabindex="-1">II. 填充 - 清空 - 使用框架，实现可持续的生产力与创造力 <a class="header-anchor" href="#ii-填充-清空-使用框架-实现可持续的生产力与创造力" aria-label="Permalink to &quot;II. 填充 - 清空 - 使用框架，实现可持续的生产力与创造力&quot;">​</a></h2><p>这个框架可以被任何人使用，但最适合处于创作者领域的人。知识工作者、意识工作者、营销人员、创意人士以及其他<a href="https://thedankoe.com/the-future-of-work-will-be-play/" target="_blank" rel="noreferrer">与体力劳动工作相反</a>的职业。也就是那些用头脑创造价值，并在网上发布他们深度研究发现、观点和创作品的人。</p><p>这封信将致力于解析我不久前写的一条推文背后的深刻含义。</p><blockquote><p>在下午用书籍、学习和社交来填充（Fill）你的大脑\\</p><p>在睡前用写日记、做计划和冥想来清空（Empty）你的大脑\\</p><p>在早上用创造、输出和专注来使用（Use）你的大脑</p><p>—— 丹·柯（DAN KOE，@thedankoe） <a href="https://twitter.com/thedankoe/status/1456553636700504065?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年11月5日</a></p></blockquote><p>这封信还建立在一个假设上：你明白满足自身基本需求的重要性。你的心理机制天生就是为了生存而设定的。如果你对外部世界有任何依恋——任何形式的关系——当这种关系受到挑战并威胁到你的自我认同时，你将无法真实地行动。也就是说，你很难对现实敞开心扉以撬动自然的杠杆。你的依恋——或者说你自认为的需求——将成为阻碍，减缓你生产力和创造力能量的流动。</p><p>如果你<em>需要</em>某些你尚未拥有的东西，你就无法成为真实、纯粹的自己。</p><p>真实与开放是这一切的关键。</p><p>在我们正式开始之前，善意提醒一下，《柯氏通讯》（Koe Letter）的读者可以<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">只需5美元即可加入现代精通（Modern Mastery）</a> —— 这是一个致力于一人企业、个人发展、生活方式设计以及相伴而来的深度探索的社区。</p><h3 id="ii-i-填充你的大脑" tabindex="-1">II.I. 填充你的大脑 <a class="header-anchor" href="#ii-i-填充你的大脑" aria-label="Permalink to &quot;II.I. 填充你的大脑&quot;">​</a></h3><p>我们把这个阶段设定在下午，而不是早上，为什么？首先，是个人偏好。其次，因为这种方法是整体性的。那些只强调效率时间——通常是早上——的深度工作小技巧注定会失败。生产力和创造力绝不是一次性的事情，它们是一种存在状态。</p><p>这不是深度工作的问题。这是关于你参与深度玩乐、深度休息，以及<em>最后</em>才是深度工作之间的平衡和程度的问题。</p><p>对于价值创作者，也就是那些打算向世界输出美好事物的人，你必须养成有意识学习的习惯。如果不通过接触新颖的观点来扩展你的世界观、头脑和知识，你打算如何创作？在某些方面，创造力就是从多个来源提取素材并将它们融合在一起。就像解构一个主题，通过学习了解它的各个组成部分，然后像小时候玩乐高积木一样搭建出你自己的创作品。</p><p>当与你的愿景、价值观和目标保持一致时，你就可以带着理解和应用的目的去吸收信息。这可以开始作为提升你意识的载体。通过接触最符合你内心方向的信息，你开始对自己的毕生事业变得清晰。如果你不知道从哪里开始，重读那本曾经改变你思维方式的书，它会再次奏效的。</p><p>我最喜欢做这件事的方式分为两部分：</p><p><strong>1) 散步时聆听</strong></p><p>我一整天会散步好几次。早上一次，工作时间结束后一次，晚上再散步一次。这不仅对睡眠至关重要（参见：昼夜节律和阳光），还有许多其他的好处。</p><blockquote><p>拥有一间办公室非常棒，拥有一个温暖、布置精美的家就更棒了。但我的大脑在室内待上几个小时后，往往会陷入停滞。所以我去散步。一旦到了室外，我的大脑立刻就开始自由而本能地围绕我的研究主题运转。各种想法不请自来，涌入我的脑海。很快，最好的答案就会从杂乱无章的思绪中浮现。我意识到我能做什么，我应该做什么，以及我必须放弃什么。——尤金·维格纳（Eugene Wigner）</p></blockquote><p>除了运动和锻炼对健康大有裨益之外，散步本身就有些独特之处。古代大师们对它深信不疑，行业领袖们虔诚地坚持散步，世界上最受尊敬的创作者们更是将散步作为日常作息的一部分——我自己也体会到了它的巨大好处。</p><p>当我带着把学到的东西应用到当前项目（比如通讯邮件、推文、课程模块，或者任何作为意识工作载体的个人品牌所产出的东西）的意图，点开一本有声书、讲座或视频时，灵感就会源源不断地涌现。从潜意识浮现到显意识。</p><p>我会从我正在吸收的内容中时不时地捡到些金点子，但真正的魔力发生在我听到那个能触发瀑布般洞见的“对的词”时。我不确定这叫什么现象，但有时你只需要那一个词、一个字母、一个声音、一个例子、一段轶事或一个故事，就能唤起一个想法，带领你掉进提问和探索的兔子洞里。</p><p>散步是我完成最佳工作成果的方式，因为它是创造力的必需品。作为一名作家，我可以在散步时用手机构思创意、列大纲和写作，从而完成我80%的工作。这就是为什么我独特的流程被打包进了<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">两小时作家（The 2 Hour Writer）</a>的原因。</p><p><strong>2) 在阳光下阅读</strong></p><p>我喜欢散步的另一个原因是，它们充当了创造力的时间块。当你走出家门，你就不会那么容易受到那些仅仅因为身处熟悉环境就会影响你学习的干扰。无论你多努力地去屏蔽那些干扰都无济于事。你知道它们就在那里，并且它们会占用你的创造力能量。</p><p>去外面晒太阳也是如此。我曾试过在散步时阅读，但结果是我总是被绊倒，还被树枝撞到头（身高6英尺5英寸确实有它的坏处）！</p><p>带着我的Kindle和一瓶圣培露（San Pellegrino）去我公寓的游泳池，这让我可以专门划分出一段只用于阅读的时间。阅读——与聆听相反——使我能够集中注意力并进行更深入的学习。我可以划出那些我想要在未来几周和几个月里仔细思考的想法，以便加深理解。</p><p><em>填充大脑</em>可以在任何时间进行，而且可能会分散在你一天的各个时间段，但为了便于你自己的实验和保持头脑清晰，请先从在下午做这件事开始。如果你下午没有时间，那就把它分散在你一天当中。我将在下面给出我个人的例子。</p><p>如果你不确定该学什么、如何捕捉想法，并且想要培养自己快速轻松地学习某个主题的能力——<a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">下载我免费的7天创意挑战。</a></p><h3 id="ii-ii-清空你的大脑" tabindex="-1">II.II. 清空你的大脑 <a class="header-anchor" href="#ii-ii-清空你的大脑" aria-label="Permalink to &quot;II.II. 清空你的大脑&quot;">​</a></h3><p>在心理学中，有一种叫做默认模式网络（Default Mode Network，简称DMN）的东西。根据《休息》（<em>Rest</em>）一书，DMN是“一系列相互连接的大脑区域，一旦人们停止专注于外部任务，它就会被激活，并将认知从外向聚焦转变为内向聚焦。”</p><p>当通过休息、冥想或开放式的活动被“激活”时，大脑的活跃度丝毫不亚于从事专注工作，或者需要<a href="https://thedankoe.com/how-to-master-your-focus/" target="_blank" rel="noreferrer">狭窄焦点</a>和集中注意力的活动时的活跃度。</p><p>这可以与临在、臣服和神圣的灵感联系在一起。当你的焦点是开放的，你的潜意识仍在努力工作并咀嚼着问题。很多程序员对这一点深有体会。他们通常在做项目时遇到bug，苦苦试图修复，然后“放弃”去干点别的日常琐事。就在最意想不到的时候，完美的解决方案会突然闪现在他们脑海中，兴奋的程序员就会冲回去打开代码库去测试它。“洗澡时的灵光一闪”也是这样的例子。</p><p>从个人经验来看，最伟大的洞见往往在经历一段挣扎之后降临。我的注意力陷入了大脑里激烈进行的自然交战中，直到我看出它的毫无意义。当你对生活中的某个问题过度关注时，解决它的最好方法其实是反直觉的。放手——也就是臣服——并融入生活本身，答案自然会浮现在脑海中。要有信心 😉</p><blockquote><p>清空你的大脑，无形无相。像水一样。你把水倒进杯子里，它就成了杯子的形状。你把水倒进瓶子里，它就成了瓶子的形状。你把它倒进茶壶里，它就成了茶壶。水可以流淌，也可以冲击。像水一样吧，我的朋友。——李小龙（Bruce Lee）</p></blockquote><p>每个人都应该熟悉这句名言，但你到底该如何清空大脑呢？</p><p>通过让自己沉浸在当下。<a href="https://thedankoe.com/why-you-wont-change-how-to-reinvent-yourself/" target="_blank" rel="noreferrer">顺应生命的河流及其带来的高潮与低谷。</a></p><p>有很多方法可以让你更容易掌握这一点，但要明白，所有这些手段都殊途同归。这里有几种方法可以让你练习沉浸在当下：</p><p><strong>1) 健身房</strong></p><p>健身房老铁们经常谈论“念动一致”（mind-muscle connection）和其他一些概念，这实际上就是将注意力锚定在当下的简称。当你在健身房时，做一个沉默的观察者。观察你脑海中那个叫你放弃的声音。观察肌肉收缩时的感觉。观察血液在你体内加速流动的状态。</p><p>这适用于任何运动，不仅限于健身房。那些容易观察到的活跃的身体机能，让你更容易把健身当作一种冥想练习。</p><p><strong>2) 沐浴自然</strong></p><p>还有什么比直接接触“本源”（Source）本身更好的方式来汲取源泉呢？</p><p>从心理学角度来看，大自然呈现了进入心流（flow）的完美配方。在徒步旅行时，你通过对徒步过程的愿景来梳理你的意识。你在脑海中构建了一个目标层级，让你在攀登时获得清晰感。你可能有一个饮水目标、距离目标、健康目标，或者只是想在大自然中度过一段美好时光的目标。这就是意图。</p><p>接着，你开始沿着小径向上攀登，并面临挑战。这个挑战是否太难，以至于让你心烦意乱，或者让你陷入无法实现愿景的消极想法中？又或者挑战太容易，让你感到失望。更棒的情况是，你计划的徒步旅行刚好匹配你的技能水平，你不需要无休止地思考。徒步旅行变成了一种艺术形式，你随之进入了心流。</p><p><strong>3) 你可以养成的其他冥想习惯</strong></p><p>有意识的冥想（这是显而易见的）、有意识的散步、在对话中有意识的倾听、有意识的写作、有意识的创作——你能开始看懂我在这里描绘的图景了吗？</p><blockquote><p>该工作时工作。\\</p><p>该休息时休息。\\</p><p>该玩耍时玩耍。\\</p><p>当你沉浸在当下时，这一切并没有区别。\\</p><p>该生活时生活。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1543552638293254144?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">July 3, 2022</a></p></blockquote><p>在自我提升领域存在一个大问题，每个人都容易陷入其中，包括我自己。当你刚开始起步，甚至当你在这个领域深耕时，你只不过是在做别人告诉你去做的事情。大多数人都在无意识地冥想，这是一个滑稽的例子。他们机械地走个过场，因为这已经成为了一种习惯。如果他们只是在任何特定时刻——而不仅仅是在冥想时——把保持意识放在首位，他们本来能获得很多好处，但现在却没有。</p><p>在这种语境下，我解释意识的最好方式是通过理解相对主义。任何不是绝对真理（不可知或仅用语言无法表达的事物）的东西都是相对的。相对意味着存在一种关系。因与果。两极性。没有这一个，另一个就无法存在。在冥想期间，你能否顺着一个想法追踪到另一个想法，再到一个事件，直到界限变得模糊，从而瞥见无限？</p><p>当你写作时，你能发现你理解中的空白吗？你能否顺着一个段落，意识到缺少了什么，从而打破“写作瓶颈”？你能看出我是如何将概念编织进这篇文章，并将它们与其他看似不相关——实则并非如此，因为一切都是相对的——的概念联系起来的吗？</p><p>顺便提一句，这就是我写作的秘诀。我选择一个我了解的主题，并以我根据自身直接经验所理解的方式去填补空白。意识流写作，然后进行编辑。如果你无法接入无限的意识流，问问自己为什么。质疑会将觉知的灯光照向阻力，并让其消散。</p><p><strong>4) 物理媒介</strong></p><p>梳理意识或创造清晰感的另一种方法是表达你脑海中那些未经组织的杂乱想法。这可以通过写作或说话来完成。</p><p>我最喜欢的方法是我的好朋友 <a href="https://twitter.com/heyjoeyjustice" target="_blank" rel="noreferrer">乔伊·贾斯蒂斯 (Joey Justice)</a> 演示给我的。那个方法就是大脑清空式写日记。你如何进行大脑清空式日记？首先，写下你脑海中能注意到的每一件事。一旦你把所有的想法、对感觉的反应、情绪和任务杂乱无章地写在纸上——你就可以开始组织它们了。</p><p>这就是建立联系和获得清晰感的地方。你可以将页面上的条目组织成特定类别、潜在项目、深度工作（deep work）优先级，以及通过清空大脑所产生的联系构建的其他任何关系。</p><p>这不仅能让你的大脑平静下来并为你入睡做准备——这也是我喜欢在晚上做这件事的原因——它还可以作为对未来几个月、几周或几天有意识的意图规划环节。</p><p><em>通过将你的注意力从工作上移开并放在生活上，两者之间的隔阂就会消散，未知之境会将你一直在寻找的洞见传递到你显意识的最前端。</em></p><p>这一层面也融入了我作为作家的工作之中，我只是 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">选择在网上这样做，以便我能以此为生。</a> 通过把社交媒体当作一本“公开日记”，我一石二鸟。</p><h3 id="ii-iii-使用你的心智" tabindex="-1">II.III. 使用你的心智 <a class="header-anchor" href="#ii-iii-使用你的心智" aria-label="Permalink to &quot;II.III. 使用你的心智&quot;">​</a></h3><p>我经常谈论专注工作。我也谈过 <a href="https://thedankoe.com/how-to-master-your-focus/" target="_blank" rel="noreferrer">专注背后的深度</a>，大多数人对此一带而过，即使它是将我们与其他生物区分开来的主要因素。</p><p>使用你的心智排在最后，因为我们已经<em>填满</em>并<em>清空</em>了我们的心智。通过填满心智，我们扩展了它，拓宽了我们的觉知，并让“灵感行动法则”发挥作用。这为我们<em>使用</em>心智时提供了新鲜的创造性火力。通过清空心智，我们让默认模式网络发挥作用。我们的潜意识会将洞察传递给显意识，我们可以通过大脑清空式日记来梳理这些意识。</p><p>当进入深度、专注的工作时，有3个主要因素会发挥作用：</p><ol><li>杠杆化的熟悉感</li><li>有序的意识</li><li>与未知之境的连接</li></ol><p>我们已经勾选了其中一些选项——比如通过写日记来梳理意识——但在不同的背景下，每件事都有不同的目的。我们进行专注工作的目标是消除干扰，进入心流，并在我们有限的创造性精力所允许的短时间内产出高质量的工作成果。</p><p>杠杆化的熟悉感是一种柔和的晨间惯例。人类大脑喜欢节省浪费在熟悉事物上的能量。因此，习惯的养成如此受欢迎，比如把你生活中特定的、最好是有益的方面置于自动驾驶状态。和大多数事物一样，“习惯”一词也有其深度。存在心理上的、情感上的、身体上的和财务上的习惯，每一个都可以进一步分解，让我们得以一窥我们在无意识的生活中究竟有多像机器人。</p><p>杠杆化的熟悉感就是如此。保持意识，认识到你的晨间惯例是熟悉的，并通过对你直接经验的觉知，始终保持与未知之境或无限的连接。对于我的埃克哈特·托利（Eckhart Tolle）粉丝们来说，简单来讲，这意味着处于“当下”——因为你只能“知道”那些你能从熟悉的过去或潜在的未来投射到现实上的东西。</p><p>有序的意识在你的日常惯例中发挥作用。拥有熟悉的起床时间、工作环境以及在开始工作时几乎没有阻力，是保存创造性能量的关键。如果你还没有通过晚间的大脑清空来规划你的早晨，你可以为你的工作设定一个理想但有挑战性的结果，以及2-3个能切实推动实现该结果的优先级任务。当这种微观目标层级与宏观目标——你的人生愿景和目标——保持一致时，心流状态应该会无缝降临。</p><blockquote><p>解锁深度专注有3个步骤\\</p><p>1. 目标（方向）<br> 2. 计划（清晰度）<br> 3. 减少阻力（行动）\\</p><p>一个渴望的结果 + 知道如何到达那里 + 简单的执行 = 让你进入对干扰麻木的心流状态。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1485985074453618688?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">January 25, 2022</a></p></blockquote><p><em>深呼吸几次，假设自己一无所知，然后开始工作。</em></p><h2 id="我的获取灵感与自我实验的日常惯例" tabindex="-1">我的获取灵感与自我实验的日常惯例 <a class="header-anchor" href="#我的获取灵感与自我实验的日常惯例" aria-label="Permalink to &quot;我的获取灵感与自我实验的日常惯例&quot;">​</a></h2><p>就像查尔斯·达尔文（Charles Darwin）一样，我喜欢用长时间的散步来划分我的专注工作时间块。我以不带手机的45分钟长距离散步开启我的早晨。我把注意力集中在我的呼吸、身体和任何我能注意到的感觉上。我的意图是，在工作时间到来之前，让自己扎根于“一无所知”的状态。有时，如果在散步时发现一张舒适的长椅，我也会在手机上用Kindle稍微看点书。</p><p>散步结束后，我会去距离大约10分钟路程的本地咖啡馆。我会点一杯我常喝的热美式，拍张照片发在Instagram动态里，然后屏蔽任何及所有可能让我从写作中分心的事物。我戴上我的AirPods（尽管有那令人畏惧的电磁场频率！），播放能帮我将特定能量导入写作的音乐，并让我的文字在已知与未知之间起舞。</p><p>在经过2-3个四十五分钟的工作时间块——中间穿插个洗手间休息——之后，我会走回家吃饭。我喜欢在工作时进行短时间的“禁食”。空腹时我总是头脑更清醒。吃完饭后，我要么去健身房，要么再出去进行一次长途散步。这次我会听有声读物或讲座来拓展我的思维。我将其兼作意识训练，通过密切关注传入耳中的词句，并允许我的好奇心通过提问来开辟新的心智路径。</p><p>当中午到来时，我这一天基本就赢了。如果我必须补些写作（比如我现在下午5点正在写，为了在明早前完成这篇），那我就去写。否则，我会阅读、社交、跑跑腿，或者通过其他媒介娱乐自己——我确实很享受看看经典的网飞（Netflix）。</p><p>到了睡觉时间，我会拿出笔记本，写下脑海里浮现的所有事情。早晨的优先级任务？搞定。自我反思？搞定。与目标对齐？搞定。极度的精神清澈？搞定。在写日记这种简单做法的背后，有着如此明确的目的和深度，这让我非常期待每天的这些时刻。这往往是我对自己了解得最多的时候，因而也是我对这个世界了解得最多的时候。</p><p>总而言之，我的日常作息可能看起来和其他人差不多。区别在于随着时间推移培养出的意识深度。如果你问其他人为什么走那么多路，他们可能无法像武器库般抛出10多个不同的“为什么”来解释这其中的原因。这种生活方式的方方面面都是经过刻意设计的。我希望你能从我的经验中汲取灵感，去实践尝试，并直接觉知到那些能提升你生活质量的存在模式。</p><p>如果你喜欢这封信，我很乐意听听你的想法。只需点击回复，告诉我到底是什么让你进行了比平时更深入的思考。</p><p>— 丹·“<em>有时</em>我说得挺有道理”·柯</p><hr><p><a href="/en/letters/the-3-part-daily-routine-for-maximum-productivity">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',98))])}const _=p(h,[["render",m]]);export{g as __pageData,_ as default};
